package com.hbm.machine.solarboiler;
import com.hbm.api.machine.MachineView;import com.hbm.energy.NodeConnection;import com.hbm.fluid.*;import com.hbm.fluid.network.*;import com.hbm.multiblock.DummyableBlock;import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;
/** Original mirror heat accumulator:50heat per1mBwater,100mBsteam; residualheat discarded each actual tick. */
public final class SolarBoilerBlockEntity extends BlockEntity implements StandardFluidTransceiver,MachineView,com.hbm.api.machine.IFluidCopiable {
 public final FluidTank water=new FluidTank(HbmFluids.WATER,100),steam=new FluidTank(HbmFluids.fromName("STEAM"),10000);public int display,heat;public final Set<BlockPos> primary=new HashSet<>(),secondary=new HashSet<>();private FluidPorts ports;
 public SolarBoilerBlockEntity(BlockPos pos,BlockState state){super(SolarBoilerContent.BOILER_BE.get(),pos,state);}@Override public boolean isValidBlockState(BlockState state){return super.isValidBlockState(state)&&DummyableBlock.isCore(state);}
 public static void tick(Level level,BlockPos pos,BlockState state,SolarBoilerBlockEntity machine){if(level instanceof ServerLevel server)machine.serverTick(server);else{machine.secondary.clear();machine.secondary.addAll(machine.primary);machine.primary.clear();}}
 private void serverTick(ServerLevel server){if(ports==null)ports=new FluidPorts(new BlockPos[]{worldPosition,worldPosition.above(2)},new NodeConnection[]{new NodeConnection(worldPosition.below(),Direction.DOWN),new NodeConnection(worldPosition.above(3),Direction.UP)});ports.update(server,this);int process=heat/50;display=process;process=Math.min(process,water.getFill());process=Math.min(process,(steam.getMaxFill()-steam.getFill())/100);if(process<0)process=0;water.setFill(water.getFill()-process);steam.setFill(steam.getFill()+process*100);heat=0;setChanged();send(server,15);}
 private void send(ServerLevel server,int range){var packet=getUpdatePacket();for(var player:server.players())if(player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<(double)range*range)player.connection.send(packet);}
 public boolean portConnects(BlockPos pos,Direction side){return pos.equals(worldPosition)&&side==Direction.DOWN||pos.equals(worldPosition.above(2))&&side==Direction.UP;}
 @Override public boolean canConnect(HbmFluidType type,Direction side){return side==Direction.UP||side==Direction.DOWN;}@Override public FluidTank[] getAllTanks(){return new FluidTank[]{water,steam};}@Override public FluidTank[] getReceivingTanks(){return new FluidTank[]{water};}@Override public FluidTank[] getSendingTanks(){return new FluidTank[]{steam};}@Override public FluidTank getTankToPaste(){return null;}
 @Override public long transferFluid(HbmFluidType type,int pressure,long amount){long rest=StandardFluidTransceiver.super.transferFluid(type,pressure,amount);if(rest!=amount)setChanged();return rest;}@Override public void useUpFluid(HbmFluidType type,int pressure,long amount){StandardFluidTransceiver.super.useUpFluid(type,pressure,amount);setChanged();}
 private void disconnect(){if(level instanceof ServerLevel server&&ports!=null)ports.remove(server);ports=null;}@Override public void setRemoved(){disconnect();super.setRemoved();}@Override public void onChunkUnloaded(){disconnect();super.onChunkUnloaded();}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);water.writeToNBT(tag,"water");steam.writeToNBT(tag,"steam");}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);water.readFromNBT(tag,"water");steam.readFromNBT(tag,"steam");}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();saveAdditional(tag,lookup);tag.putInt("display",display);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){loadAdditional(tag,lookup);display=tag.getInt("display");}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection connection,ClientboundBlockEntityDataPacket packet,HolderLookup.Provider lookup){handleUpdateTag(packet.getTag(),lookup);}
 @Override public long energyStored(){return 0;}@Override public long energyCapacity(){return 0;}@Override public List<TankView> tanks(){return List.of(new TankView(water.getTankType(),water.getFill(),water.getMaxFill()),new TankView(steam.getTankType(),steam.getFill(),steam.getMaxFill()));}@Override public List<ProgressView> progressBars(){return List.of(new ProgressView("gui.hbm.solar_boiler.heating",display,100,0xffdd00));}
}
